// point (x, y): x = pixels from the LEFT, y = pixels from the TOP
// origin (0, 0) = top-left;  VGA screen = 640 x 480

putpixel(x, y, color);                // one dot at (x, y)
int maxX = getmaxx();                 // 639 on a 640 x 480 screen
int maxY = getmaxy();                 // 479 on a 640 x 480 screen

// rectangle with top-left (left, top) and bottom-right (right, bottom)
int width  = right - left;            // how wide
int height = bottom - top;            // how tall
int cx = (left + right) / 2;          // center x
int cy = (top + bottom) / 2;          // center y

sample.code:
#include <graphics.h>
#include <conio.h>

int main()
{
    int gd = DETECT, gm;
    initgraph(&gd, &gm, (char*)"");
    putpixel(0, 0, WHITE);
    putpixel(100, 50, YELLOW);
    putpixel(300, 200, LIGHTGREEN);
    for (int x = 400; x <= 600; x += 10)
    {
        putpixel(x, 100, RED);
    }
    getch();
    closegraph();
    return 0;
}

#include <iostream>
using namespace std;

int main()
{
    int left = 100, top = 50, right = 400, bottom = 250;
    int width = right - left;
    int height = bottom - top;
    int cx = (left + right) / 2;
    int cy = (top + bottom) / 2;
    cout << "Width  = " << width << endl;
    cout << "Height = " << height << endl;
    cout << "Center = (" << cx << ", " << cy << ")" << endl;
    return 0;
}

